sysauto_script.script:
(function sendUpcomingTaskReminders() {
    var today = new GlideDateTime();
    var twoDaysLater = new GlideDateTime();
    twoDaysLater.addDaysUTC(2);

    var taskGR = new GlideRecord('x_1790229_event_ma_event_task');
    taskGR.addNotNullQuery('u_due_date');
    taskGR.addQuery('u_due_date', '>=', today);
    taskGR.addQuery('u_due_date', '<=', twoDaysLater);
    taskGR.query();

    var reminderMap = {}; // {event_sys_id: {manager, eventName, tasks: []}}

    while (taskGR.next()) {
        var event = taskGR.u_event;
        if (!event || !event.u_event_manager) continue;

        var eventId = event.sys_id.toString();
        if (!reminderMap[eventId]) {
            reminderMap[eventId] = {
                eventName: event.u_event_name + ' (' + event.number + ')',
                manager: event.u_event_manager,
                tasks: []
            };
        }

        reminderMap[eventId].tasks.push({
            name: taskGR.u_task_name + '',
            due: taskGR.getDisplayValue('u_due_date')
        });
    }

    // Send one email per manager per event
    for (var Id in reminderMap) {
        var data = reminderMap[Id];
        var manager = data.manager;

        if (!manager || !manager.email) {
            gs.warn('No planner email for event: ' + data.eventName);
            continue;
        }

        var body = 'Upcoming Tasks for Event: ' + data.eventName + '\n\n';
        body += 'Task Name | Due Date\n';
        body += '---------------------------\n';

        data.tasks.forEach(function(task) {
            body += task.name + ' | ' + task.due + '\n';
        });

        gs.eventQueue(
            'x_1790229_event_ma.upcoming_task_reminder',
            new GlideRecord('sys_user').get(manager.sys_id),
            data.eventName,
            body
        );
    }
})();
